using System.Security.Claims; using System.Text; using Microsoft.AspNetCore.Authentication.JwtBearer; using Microsoft.EntityFrameworkCore; using Microsoft.IdentityModel.Tokens;
namespace RaceDay.Api;
public partial class Program {
 public static void Main(string[] args) { var b=WebApplication.CreateBuilder(args); b.Services.AddDbContext<RaceDayDbContext>(o=>o.UseSqlServer(b.Configuration.GetConnectionString("RaceDay"))); b.Services.AddControllers(); b.Services.AddEndpointsApiExplorer(); b.Services.AddSwaggerGen(); b.Services.AddScoped<TokenService>(); b.Services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme).AddJwtBearer(o=>o.TokenValidationParameters=new(){ValidateIssuer=true,ValidateAudience=true,ValidateLifetime=true,ValidateIssuerSigningKey=true,ValidIssuer=b.Configuration["Jwt:Issuer"],ValidAudience=b.Configuration["Jwt:Audience"],IssuerSigningKey=new SymmetricSecurityKey(Encoding.UTF8.GetBytes(b.Configuration["Jwt:Key"]!))}); b.Services.AddAuthorization(); var app=b.Build();  app.UseSwagger(); app.UseSwaggerUI(); app.UseHttpsRedirection(); app.UseAuthentication(); app.UseAuthorization(); app.MapControllers(); app.Run(); }
}
public class TokenService(IConfiguration config) { public string Create(User u) { var claims=new[]{new Claim(ClaimTypes.NameIdentifier,u.UserId.ToString()),new Claim(ClaimTypes.Name,u.Username),new Claim(ClaimTypes.Role,u.Role)}; var key=new SymmetricSecurityKey(Encoding.UTF8.GetBytes(config["Jwt:Key"]!)); return new System.IdentityModel.Tokens.Jwt.JwtSecurityTokenHandler().WriteToken(new System.IdentityModel.Tokens.Jwt.JwtSecurityToken(config["Jwt:Issuer"],config["Jwt:Audience"],claims,expires:DateTime.UtcNow.AddMinutes(config.GetValue<int>("Jwt:ExpiryMinutes")),signingCredentials:new SigningCredentials(key,SecurityAlgorithms.HmacSha256))); } }
public static class ClaimsExtensions { public static int UserId(this ClaimsPrincipal user)=>int.Parse(user.FindFirst(ClaimTypes.NameIdentifier)!.Value); }
